contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint valueSent) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (valueSent)); require(valueSent <= 1000000000000000000000000000000);
        require(address(this).balance >= valueSent);

        bool reverted;
        c.play{value: valueSent}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted == (valueSent != 10));
    }

    receive() external payable {}
}

