// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 valueSent) internal {
        valueSent = bound(valueSent, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= valueSent);
        bool reverted;
        try c.play{value: valueSent}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == (valueSent != 10));
    }

    function testFuzz_run(uint256 valueSent) public {
        _run(valueSent);
    }

    receive() external payable {}
}
